create table public.roi_transactions ( id uuid primary key default gen_random_uuid(), transaction_date date not null, transaction_type text not null check (transaction_type in ('expense', 'payout')), amount numeric not null check (amount > 0), note text, image_url text, account_id uuid references public.accounts(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now() );